"""
Shared logging sink for observation store, smart retriever, and ReAct routing.

setup_session_log() redirects sys.stdout to a TeeStream that writes to both
the console and a timestamped file, so ALL stdout output — including DSPy's
verbose=True internal prints — is captured automatically.

rlm_log(msg) is a drop-in replacement for print() in observation_store,
smart_retriever, and react; it also triggers setup_session_log() lazily on
first call so no explicit wiring is needed.

Log file location:
  defaults to the current working directory
  override via env var RLM_LOG_DIR
"""

import logging
import os
import sys
import atexit
from datetime import datetime


class _TeeStream:
    """Mirrors every write to both the original stdout and a log file."""

    def __init__(self, original, file):
        self._original = original
        self._file = file

    def write(self, text: str) -> int:
        self._original.write(text)
        self._file.write(text)
        return len(text)

    def flush(self) -> None:
        self._original.flush()
        self._file.flush()

    def isatty(self) -> bool:
        return self._original.isatty()

    def __getattr__(self, name):
        return getattr(self._original, name)


_log_file = None
_original_stdout = None


def setup_session_log() -> str:
    """
    Redirect sys.stdout to a TeeStream that also writes to a timestamped file.
    Idempotent — safe to call multiple times.  Returns the log file path.
    """
    global _log_file, _original_stdout
    if _log_file is not None:
        return _log_file.name

    log_dir = os.environ.get("RLM_LOG_DIR", ".")
    os.makedirs(log_dir, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    log_path = os.path.join(log_dir, f"rlm_log_{timestamp}.txt")

    _original_stdout = sys.stdout
    _log_file = open(log_path, "w", encoding="utf-8", buffering=1)
    _log_file.write(f"=== RLM Session Log  {datetime.now().isoformat()} ===\n\n")
    sys.stdout = _TeeStream(_original_stdout, _log_file)

    # DSPy RLM verbose=True uses logging.getLogger("dspy.predict.rlm").info(...)
    # which goes to stderr by default — missed by the stdout TeeStream.
    # Wire a StreamHandler to the now-TeeStreamed sys.stdout so the verbose
    # reasoning steps appear on the console AND land in the log file.
    _rlm_pylogger = logging.getLogger("dspy.predict.rlm")
    _rlm_pylogger.setLevel(logging.INFO)
    _handler = logging.StreamHandler(stream=sys.stdout)  # sys.stdout is TeeStream now
    _handler.setLevel(logging.INFO)
    _handler.setFormatter(logging.Formatter("%(message)s"))
    _rlm_pylogger.addHandler(_handler)
    _rlm_pylogger.propagate = False  # prevent duplicate copy going to stderr

    atexit.register(_teardown)
    print(f"[RLM LOGGER] logging to {log_path}")
    return log_path


def _teardown() -> None:
    global _log_file, _original_stdout
    # Remove the logging handler we attached so it doesn't outlive the file
    _rlm_pylogger = logging.getLogger("dspy.predict.rlm")
    for h in list(_rlm_pylogger.handlers):
        _rlm_pylogger.removeHandler(h)
    if _original_stdout is not None:
        sys.stdout = _original_stdout
    if _log_file and not _log_file.closed:
        _log_file.flush()
        _log_file.close()


def rlm_log(msg: str) -> None:
    """
    Drop-in replacement for print() in RLM-related modules.
    Triggers setup_session_log() lazily on first call, then prints through
    the TeeStream so both the console and the log file receive the message.
    """
    setup_session_log()
    print(msg)
